import type { Response } from 'express';
import { injectPreviewBridge } from '../proxy-middleware/preview-bridge';
import { isConfinedRelativePath } from '../utils/pathContainment';

export type VariantPreviewBridgeOptions = {
  isEnabled: boolean;
  expectedParentOrigin?: string;
  resolveLibraryOrigin?: () => string | undefined;
};

export const getInvalidRawHistoryPreviewAssetPath = (
  rawUrl: string,
): string | null => {
  const rawPath = rawUrl.split('?')[0] ?? '';
  const marker = '/preview/';
  const markerIndex = rawPath.indexOf(marker);
  if (markerIndex === -1) return null;
  const rawAssetPath = rawPath.slice(markerIndex + marker.length);
  let decodedAssetPath = '';
  try {
    decodedAssetPath = decodeURIComponent(rawAssetPath);
  } catch {
    return rawAssetPath;
  }
  return isConfinedRelativePath(decodedAssetPath) ? null : decodedAssetPath;
};

const PREVIEW_CDN_HOSTS = [
  'https://unpkg.com',
  'https://cdn.jsdelivr.net',
  'https://cdnjs.cloudflare.com',
  'https://esm.sh',
  'https://cdn.skypack.dev',
].join(' ');

const buildStaticPreviewCsp = (
  parentFrameOrigin?: string,
  libraryOrigin?: string,
): string => {
  const frameAncestors = ["'self'", parentFrameOrigin, libraryOrigin]
    .filter(Boolean)
    .join(' ');
  return [
    "default-src 'self' data: blob:",
    `script-src 'self' 'unsafe-inline' blob: ${PREVIEW_CDN_HOSTS}`,
    `style-src 'self' 'unsafe-inline' ${PREVIEW_CDN_HOSTS}`,
    "img-src 'self' data: blob: https:",
    `font-src 'self' data: ${PREVIEW_CDN_HOSTS}`,
    `connect-src 'self' blob: ${PREVIEW_CDN_HOSTS}`,
    "frame-src 'self' https: data: blob:",
    `frame-ancestors ${frameAncestors}`,
    "base-uri 'self'",
  ].join('; ');
};

export const sendStaticPreviewHtml = ({
  res,
  html,
  previewBridge,
}: {
  res: Response;
  html: string;
  previewBridge?: VariantPreviewBridgeOptions;
}): void => {
  const body = previewBridge?.isEnabled
    ? injectPreviewBridge(html, {
        expectedParentOrigin: previewBridge.expectedParentOrigin,
      })
    : html;
  res
    .status(200)
    .type('html')
    .set('Cache-Control', 'no-store')
    .set(
      'Content-Security-Policy',
      buildStaticPreviewCsp(
        previewBridge?.expectedParentOrigin,
        previewBridge?.resolveLibraryOrigin?.(),
      ),
    )
    .set('X-Content-Type-Options', 'nosniff')
    .send(body);
};
